public class TimeRangeBuilder {

    private static final long FETCH_DATA_DURATION = 1000 * 60 * 60 * 24; // 24 hours in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start;

        while (currentEnd <= end) {
            if (currentEnd - currentStart > FETCH_DATA_DURATION) {
                timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
                currentStart += FETCH_DATA_DURATION;
                currentEnd += FETCH_DATA_DURATION;
            } else {
                timeRanges.add(new TimeRange(currentStart, currentEnd));
                break;
            }
        }

        return timeRanges;
    }

    // Example TimeRange class
