public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    int length = str.length();
    int utf8Length = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Length++;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            utf8Length += 3;
        } else {
            // Surrogate pair
            i++;
            utf8Length += 4;
        }
    }
    lb.ensureCapacity(utf8Length);
    int offset = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.put((byte) c);
        } else if (c < 0x800) {
            lb.put((byte) (0xC0 | (c >> 6)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        } else if (c < 0xD800 || c > 0xDFFF) {
            lb.put((byte) (0xE0 | (c >> 12)));
            lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        } else {
            // Surrogate pair
            i++;
            int codePoint = Character.toCodePoint(c, str.charAt(i));
            lb.put((byte) (0xF0 | (codePoint >> 18)));
            lb.put((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (codePoint & 0x3F)));
        }
    }
    return lb;
}

