public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i < str.length()) {
                c = str.charAt(i);
                switch (c) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case 'b':
                        result.append('\b');
                        break;
                    case 'f':
                        result.append('\f');
                        break;
                    case '\\':
                        result.append('\\');
                        break;
                    case '"':
                        result.append('"');
                        break;
                    case '\'':
                        result.append('\'');
                        break;
                    default:
                        throw new Exception("Invalid escape sequence: \\" + c);
                }
            } else {
                throw new Exception("Invalid escape sequence: \\\\");
            }
        } else {
            result.append(c);
        }
        i++;
    }
    return result.toString();
}

